import React from "react";
import { render, fireEvent, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import Checkbox from "../Checkbox";
import * as stories from "./CheckboxGroup.stories";
import CheckboxGroup from "./CheckboxGroup";

const { Basic } = composeStories(stories) as any;

describe("CheckboxGroup", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("should call onChange when uncontrolled", () => {
    const handleChange = jest.fn((_: any, value: any) => value);
    render(
      <CheckboxGroup onChange={handleChange}>
        <Checkbox value="A" label="A" />
        <Checkbox value="B" label="B" />
        <Checkbox value="C" label="C" />
      </CheckboxGroup>
    );

    fireEvent.click(screen.getByText("A"));

    expect(handleChange.mock.calls[0][1]).toEqual(["A"]);
  });

  it("should handle a default value when uncontrolled", () => {
    render(
      <CheckboxGroup defaultValue={["B"]}>
        <Checkbox value="A" label="A" />
        <Checkbox value="B" label="B" />
        <Checkbox value="C" label="C" />
      </CheckboxGroup>
    );
    expect(screen.getByLabelText("B")).toBeChecked();
  });

  it("should call onChange when controlled", () => {
    const handleChange = jest.fn((_: any, value: any) => value);
    render(
      <CheckboxGroup value={["A"]} onChange={handleChange}>
        <Checkbox value="A" label="A" />
        <Checkbox value="B" label="B" />
        <Checkbox value="C" label="C" />
      </CheckboxGroup>
    );

    fireEvent.click(screen.getByText("B"));

    expect(handleChange.mock.calls[0][1]).toEqual(["A", "B"]);
  });

  it("passes through props", () => {
    render(
      <CheckboxGroup value={["A"]} data-testid="checkboxgroup"></CheckboxGroup>
    );
    expect(screen.queryByRole("group")).toHaveAttribute(
      "data-testid",
      "checkboxgroup"
    );
  });

  it("generate unique name if unspecified", () => {
    render(
      <CheckboxGroup>
        <Checkbox value="A" label="A" />
      </CheckboxGroup>
    );
    const radio = screen.queryByRole("checkbox") as HTMLElement;
    expect(radio.getAttribute("name")).toMatch(/^checkboxgroup-/);
  });

  it("use name prop if specified", () => {
    render(
      <CheckboxGroup name="groupname">
        <Checkbox value="A" label="A" />
      </CheckboxGroup>
    );
    expect(screen.queryByRole("checkbox")).toHaveAttribute("name", "groupname");
  });
});
